// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address user, uint depositAmount, uint cashOutAmount) public {
        vm.assume(depositAmount >= 1 ether && depositAmount < 10000 ether);
        vm.assume(cashOutAmount <= 5000 ether);

        // Fund user and make deposit
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        uint balanceBefore = c.balances(user);

        // Attempt cash out
        vm.prank(user);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.CashOut.selector, cashOutAmount));

        if (cashOutAmount <= balanceBefore) {
            // If cashOutAmount <= balance, the reference succeeds and balances decrease by cashOutAmount
            // The buggy version reverts after decreasing balances, so balances don't change
            // Rule: balances(user) == balanceBefore - cashOutAmount (if call succeeded) OR 
            //       balances(user) == balanceBefore (if call reverted due to bug)
            // But the reference always succeeds and updates balances correctly, 
            // while the buggy version reverts and leaves balances unchanged.
            // So we assert: if call reverts, balances unchanged; if call succeeds, balances decreased.

            // For the reference C, the call should always succeed when cashOutAmount <= balanceBefore
            assertTrue(success, "Reference CashOut should succeed");

            // After successful reference CashOut, balance should be balanceBefore - cashOutAmount
            uint balanceAfter = c.balances(user);
            assertTrue(balanceAfter == balanceBefore - cashOutAmount, "Reference balance should decrease by cashOutAmount");
        } else {
            // When cashOutAmount > balanceBefore, CashOut reverts in both versions (balance not updated)
            assertTrue(!success, "CashOut should revert when amount exceeds balance");
            uint balanceAfter = c.balances(user);
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged on revert");
        }
    }
}

