        // Ensure deposit is above MinDeposit to actually affect balances
        vm.assume(depositAmount > 1 ether);
        // Ensure withdrawAmount <= balance of caller after deposit
        vm.assume(withdrawAmount <= depositAmount);

        // Ensure caller has enough ether to deposit
        if (caller != address(0)) {
            vm.deal(caller, depositAmount * 2);
        }

        // Pick a different address to observe balance changes
